+func changedSemanticFiles(ctx context.Context, runner CommandRunner, repoDir string) ([]string, error) {
+	diffOutput, _, err := runner.Run(ctx, repoDir, "git", "diff", "--name-status", "-M", "-C", "HEAD")
+	if err != nil {
